setup.script:
#!/bin/sh
echo "claude $* cfg=${CLAUDE_CONFIG_DIR:-}" >> "$DIFFTEST_FAKELOG"
case "$1 $2" in
  "auth status") case "${CLAUDE_CONFIG_DIR:-}" in *work|"") echo '{"loggedIn":true}'; exit 0;; *other) echo '{"loggedIn":false}'; exit 0;; *) exit 1;; esac ;;
esac
exit 0

#!/bin/sh
echo "codex $* home=${CODEX_HOME:-}" >> "$DIFFTEST_FAKELOG"
case "$1 $2" in
  "login status") case "${CODEX_HOME:-}" in *b) echo 'Logged in'; exit 0;; *) echo 'Not logged in'; exit 1;; esac ;;
esac
exit 0

setup.text:
#!/bin/sh
has=0; for a in "$@"; do [ "$a" = --account ] && has=1; last=$a; done
echo "child: $* chain=${KITH_CHAIN_CHILD:-}"
echo "child-err: $*" >&2
case $last in
  limit-first) [ $has = 0 ] && { echo "You've hit your usage limit" >&2; exit 1; }; exit 0 ;;
  limit-stdout) [ $has = 0 ] && { echo "Rate limit exceeded"; exit 1; }; exit 0 ;;
  exit4-first) [ $has = 0 ] && { echo "not logged in" >&2; exit 4; }; exit 0 ;;
  boom) echo "boom" >&2; exit 3 ;;
  limit-all) echo "weekly limit reached" >&2; exit 1 ;;
  exit4-all) exit 4 ;;
  long-limit) i=0; while [ $i -lt 500 ]; do echo "this usage limit text is a task output line $i"; i=$((i+1)); done; exit 1 ;;
  ok) exit 0 ;;
esac
exit 0

